CREATE TABLE "airlines" (
	"iata" text PRIMARY KEY NOT NULL,
	"name" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "airlines_iata_ck" CHECK ("airlines"."iata" ~ '^[A-Z0-9]{2}$' AND "airlines"."iata" !~ '^[0-9]{2}$')
);
--> statement-breakpoint
CREATE TABLE "airports" (
	"iata" text PRIMARY KEY NOT NULL,
	"icao" text,
	"name" text NOT NULL,
	"city" text,
	"country" text,
	"lat" numeric(9, 6) NOT NULL,
	"lng" numeric(9, 6) NOT NULL,
	"tz" text NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "airports_iata_ck" CHECK ("airports"."iata" ~ '^[A-Z]{3}$'),
	CONSTRAINT "airports_icao_ck" CHECK ("airports"."icao" IS NULL OR "airports"."icao" ~ '^[A-Z0-9]{4}$'),
	CONSTRAINT "airports_tz_ck" CHECK (length("airports"."tz") BETWEEN 1 AND 64)
);
--> statement-breakpoint
CREATE UNIQUE INDEX "airports_icao_uq" ON "airports" USING btree ("icao") WHERE "airports"."icao" IS NOT NULL;
